ASSERT $context.userId IS NULL OR 'hr_admin' IN $context.role OR 'hr_manager' IN $context.role code: 'forbidden', message: 'HR only.', status: 403;
$deptTeams := SELECT org.departments { t := team._id } FILTER team IS NOT NULL;
$want := SELECT core.employees { k := concat(person._id::text, '|', department.team._id::text), u := person._id, t := department.team._id }
  FILTER status IS NOT NULL AND status != 'terminated' AND department.team IS NOT NULL;
$heads := SELECT org.departments { k := concat(head.person._id::text, '|', team._id::text), u := head.person._id, t := team._id }
  FILTER head IS NOT NULL AND team IS NOT NULL;
$have := SELECT auth.team_memberships { k := concat(user._id::text, '|', team._id::text), kind } FILTER team._id IN $deptTeams.t;
DELETE auth.team_memberships [team._id IN $deptTeams.t AND concat(user._id::text, '|', team._id::text) NOT IN $want.k AND concat(user._id::text, '|', team._id::text) NOT IN $heads.k];
INSERT auth.team_memberships EACH (SELECT $want { u, t } FILTER k NOT IN $have.k AND k NOT IN $heads.k) { team: $item.t, user: $item.u, kind: 'member' };
INSERT auth.team_memberships EACH (SELECT $heads { u, t } FILTER k NOT IN $have.k) { team: $item.t, user: $item.u, kind: 'lead' };
UPDATE auth.team_memberships [team._id IN $deptTeams.t AND concat(user._id::text, '|', team._id::text) IN $heads.k AND kind != 'lead'] { kind: 'lead' };
UPDATE auth.team_memberships [team._id IN $deptTeams.t AND concat(user._id::text, '|', team._id::text) NOT IN $heads.k AND kind == 'lead'] { kind: 'member' };
$mgrRole := SELECT auth.roles { _id } FILTER name == 'manager' TAKE 1;
$managers := SELECT core.employees { u := manager.person._id } FILTER status IS NOT NULL AND status != 'terminated' AND manager IS NOT NULL;
$holders := SELECT auth.user_roles { u := user._id } FILTER role._id IN $mgrRole._id;
DELETE auth.user_roles [role._id IN $mgrRole._id AND user._id NOT IN $managers.u AND user._id NOT IN $heads.u];
INSERT auth.user_roles EACH (SELECT auth.users { _id } FILTER (_id IN $managers.u OR _id IN $heads.u) AND _id NOT IN $holders.u) { user: $item._id, role: $mgrRole._id };
SELECT auth.team_memberships { team := team.name, user := user.name, kind } FILTER team._id IN $deptTeams.t SORT team, kind, user

ASSERT 'hr_admin' IN $context.role OR 'hr_manager' IN $context.role code: 'forbidden', message: 'HR only.', status: 403;
