$r := SELECT pto.requests { department := employee.department.name, productTeam := employee.productTeam.name, approved := CASE(status == 'approved', hours, 0), pending := CASE(status == 'pending', hours, 0) }
  FILTER startDate <= $to::date AND endDate >= $from::date;
SUMMARIZE $r { approvedHours := sum(approved), pendingHours := sum(pending), requests := count(*) } BY department, productTeam

$off := SELECT pto.requests { kind := 'timeOff', _id, startDate, endDate, hours, status, employeeName := employee.person.name, department := employee.department.name, location := employee.location.name, country := employee.location.country, ptoType := policy.ptoType.name }
  FILTER (status == 'approved' OR status == 'pending') AND startDate <= $to::date AND endDate >= $from::date
    AND ($department::uuid IS NULL OR employee.department._id == $department::uuid)
    AND ($location::uuid IS NULL OR employee.location._id == $location::uuid);
